  const layers=group('레이어');this.objectList=document.createElement('select');this.objectList.id='sceneObject';this.objectList.setAttribute('aria-label','배경 물체');layers.append(this.objectList);this.objectList.onchange=()=>{this.selected=+this.objectList.value;this.objectFields();};const hide=document.createElement('button');hide.textContent='선택 물체 숨김 / 표시';hide.onclick=()=>{if(this.selected<0)return;const a=this.settings().hidden,i=a.indexOf(this.selected);i<0?a.push(this.selected):a.splice(i,1);this.apply();this.list();editor.queueLive();};layers.append(hide);const show=document.createElement('button');show.textContent='모두 표시';show.onclick=()=>{this.settings().hidden=[];this.apply();this.list();editor.queueLive();};layers.append(show);
