 edges(){const s=this.settings();if(!s.lines)return;if(this.edgeAngle===s.edgeAngle)return;this.lines.forEach(l=>{l.removeFromParent();l.geometry.dispose();l.material.dispose();});this.lines=[];for(const o of this.meshes){if(o.isInstancedMesh)continue;const line=new T.LineSegments(new T.EdgesGeometry(o.geometry,s.edgeAngle),new T.LineBasicMaterial({color:s.lineColor}));line.userData.contiEdge=true;line.raycast=()=>{};o.add(line);this.lines.push(line);}this.edgeAngle=s.edgeAngle;}
